import {blank,uid,stamp,today,ROOTS,BUILTIN_CATEGORIES,categories,descendants,catPath,categoryName,isActive,money,inPeriod,stats,months,monthlySeries,challengeProgress,expiryInfo,supplyEstimate,validBackup,mergeData,deleteRecord,demo} from './model.mjs';
const $=sel=>document.querySelector(sel);
const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const attr=esc;
const efmt=(n,dbRef=null)=>{const currency=(dbRef||db).settings.currency||'EUR';return new Intl.NumberFormat('en-FI',{style:'currency',currency,maximumFractionDigits:2}).format(Number(n)||0)};
const shortDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-FI',{day:'numeric',month:'short',year:'numeric'}):'Not recorded';
const dt=v=>v?String(v).slice(0,10):today();
const plural=(n,s)=>`${n} ${s}${n===1?'':'s'}`;
const pct=x=>Math.min(100,Math.max(0,Number(x)||0));
const acqName={existing:'Already owned',purchase:'Purchased',gift:'Received as gift'};
const statusName={'unopened':'Unopened','in-use':'In use','finished':'Finished','decluttered':'Decluttered','gifted':'Given away'};
const touch=x=>{x.updatedAt=stamp();return x};
let lookupToken=0,db=blank(),page='home',scope=null,statsScope=null,period='year',invStatus='active',invSort='recent',search='',wishlistShow='open',challengeShow='active',openModal='',pendingInstall=null,workerWaiting=null,qr=null,media=null,scanInterval=null,scanBusy=false,saveChain=Promise.resolve(),storageError=false,toastTimer=null,editing=false,modalPayload=null;
const getProduct=id=>db.products.find(x=>x.id===id);
const getUnit=id=>db.units.find(x=>x.id===id);
const getCat=id=>categories(db).find(c=>c.id===id);
const catColor=id=>catPath(db,id)[0]?.color||'#b99afa';
const unitsFor=productId=>db.units.filter(u=>u.productId===productId);
const showToast=s=>{const root=$('#toast-root');root.innerHTML=`<div class="toast" role="status">${esc(s)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.innerHTML='',3400)};
const load=()=>new Promise((resolve,reject)=>{const request=indexedDB.open('project-pan-data',1);request.onupgradeneeded=()=>request.result.createObjectStore('state');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const conn=request.result,tx=conn.transaction('state','readonly'),q=tx.objectStore('state').get('main');q.onsuccess=()=>{conn.close();resolve(q.result||blank())};q.onerror=()=>{conn.close();reject(q.error)}}});
const persist=data=>new Promise((resolve,reject)=>{const request=indexedDB.open('project-pan-data',1);request.onerror=()=>reject(request.error);request.onsuccess=()=>{let conn=request.result,tx=conn.transaction('state','readwrite');tx.objectStore('state').put(data,'main');tx.oncomplete=()=>{conn.close();resolve()};tx.onerror=()=>{conn.close();reject(tx.error)};tx.onabort=()=>{conn.close();reject(tx.error)}}});
function save(){db.updatedAt=stamp();const snapshot=structuredClone(db);$('#saving-status').textContent='Saving…';saveChain=saveChain.catch(()=>{}).then(()=>persist(snapshot)).then(()=>{$('#saving-status').textContent='Saved';storageError=false}).catch(e=>{storageError=true;$('#saving-status').textContent='Not saved';showToast('Storage error — export a backup now');console.error(e)});return saveChain;}
function change(mutator,{silent=false}={}){mutator(db);save();render();if(!silent)showToast('Saved to your collection');}
function navigate(next){page=next;closeModal();render();window.scrollTo({top:0,behavior:'instant'})}
const btn=(text,action,other='',cls='button')=>`<button class="${cls}" data-action="${action}" ${other}>${text}</button>`;
const kicker=(title,sub='')=>`<div class="eyebrow">${esc(sub||'your collection')}</div><h1 class="page-title">${esc(title)}</h1>`;
const section=(title,right='')=>`<div class="section-heading"><h2>${title}</h2><span class="hint">${right}</span></div>`;
const labelPill=(text,kind='')=>`<span class="pill ${kind}">${esc(text)}</span>`;
const empty=(icon,title,text,button='')=>`<div class="empty"><div class="big">${icon}</div><h3>${title}</h3><p>${text}</p>${button}</div>`;
const unitLabel=u=>`${statusName[u.status]||u.status}${u.location?' · '+u.location:''}`;
const productImage=p=>p?.image&&/^(data:image\/(png|jpeg|webp);base64,|https:\/\/)/i.test(p.image)?`<img class="product-image" alt="" src="${attr(p.image)}" loading="lazy" onerror="this.style.display='none'">`:'<div class="product-image product-placeholder" aria-hidden="true">◌</div>';
const kpi=(label,n,foot='',tone='')=>`<div class="card kpi"><div class="caption">${label}</div><div class="value ${tone}">${n}</div><div class="foot">${foot}</div></div>`;
const getRecords=(scopeId=null)=>{const ids=descendants(db,scopeId);return db.units.filter(u=>ids.has(getProduct(u.productId)?.categoryId))};
const catStats=(id=null)=>stats(db,{categoryId:id,period,now:today()});
const scopeSelector=(selected,action)=>`<select id="category-filter" data-action="${action}" aria-label="Category scope"><option value="">All categories</option>${optionsForCategories(selected,true)}</select>`;
const optionLabel=(c)=>categoryName(db,c.id);
function optionsForCategories(selected='',allNodes=false){const cats=categories(db);return cats.filter(c=>allNodes||!cats.some(n=>n.parentId===c.id)).map(c=>`<option value="${attr(c.id)}" ${selected===c.id?'selected':''}>${esc(optionLabel(c))}</option>`).join('');}
const categoryOptions=selected=>`<option value="">Choose a category…</option>${optionsForCategories(selected,false)}`;
const gridCats=(parent=null,selection=false)=>{const child=categories(db).filter(c=>c.parentId===parent);return `<div class="grid category-grid">${child.map(c=>{let s=stats(db,{categoryId:c.id}),hasChild=categories(db).some(x=>x.parentId===c.id);return `<button class="cat-card" data-action="category" data-id="${attr(c.id)}" style="text-align:left"><span class="cat-dot" style="background:${attr(c.color||catColor(c.id))}"></span><div class="cat-name">${esc(c.name)} ${hasChild?'›':''}</div><div class="row between"><div class="cat-count">${s.active}</div><div class="cat-sub">${plural(s.finished,'empty')} this year</div></div></button>`}).join('')}</div>`};
const crumbs=id=>`<div class="breadcrumb"><button class="crumb" data-action="category" data-id="">All categories</button>${catPath(db,id).map(c=>`<span class="subtle">›</span><button class="crumb" data-action="category" data-id="${attr(c.id)}">${esc(c.name)}</button>`).join('')}</div>`;
const subtitleScope=id=>id?getCat(id)?.name||'Category':'All categories';
const emptyProducts=()=>empty('◌','Your collection starts here','Scan a barcode or add a product manually. Enter things you already own without counting them as new spending.',btn('＋ Add first product','add-product', '', 'button primary'));
function home(){const y=stats(db,{period:'year'}),m=stats(db,{period:'month'}),due=db.units.filter(isActive).map(u=>expiryInfo(u)).filter(e=>e&&e.level!=='fine'),activeChallenges=db.challenges.filter(c=>!c.archived).slice(0,3),recent=db.units.slice().sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,5);
 return `<div class="hero"><div><div class="eyebrow">A LITTLE LESS, A LITTLE LOVED</div><h1>Your collection,<br>in perspective.</h1><p>Track every product, enjoy the empties, and give the things you own some attention.</p><div class="row wrap">${btn('＋ Add product','add-product','','button primary')}${btn('⌗ Scan barcode','scan','','button')}</div></div><div class="hero-glyph">◌</div></div>
 <div class="grid kpis">${kpi('Products owned',y.active,`${y.inUse} in use · ${y.unopened} unopened`)}${kpi('Empties this year',y.finished,`${efmt(y.emptiesValue)} recorded cost used up${y.emptiesUnknown?' · '+y.emptiesUnknown+' unpriced':''}`,'green')}${kpi('Spent this year',efmt(y.spent),`${plural(y.purchased,'dated purchase')}${y.undatedPurchases?' · '+y.undatedPurchases+' undated':''}`)}${kpi('Collection cost',efmt(y.collectionValue),`${y.collectionUnknown} without a price`)}</div>
 ${db.units.length===0?`<div class="mt18">${emptyProducts()}</div>`:''}
 ${section('Explore categories','Tap to drill down')}${gridCats()}
 <div class="two-col mt24"><div class="card"><div class="toolbar"><div class="strong">Project Pan progress</div><button class="button small-btn quiet" data-page="pan">See projects →</button></div>${activeChallenges.length?activeChallenges.map(c=>challengeLine(c)).join(''):empty('◎','Start your first goal','Try a monthly empties challenge, a no-buy, or reducing a specific category.',btn('Create challenge','add-challenge','','button primary small-btn'))}</div>
 <div class="card"><div class="toolbar"><div class="strong">This month</div><button class="button small-btn quiet" data-page="insights">More insights →</button></div><div class="stat-split mt18"><div class="micro"><strong>${m.finished}</strong><span>Empties</span></div><div class="micro"><strong>${m.purchased}</strong><span>Purchased</span></div><div class="micro"><strong>${efmt(m.spent)}</strong><span>Spent</span></div></div><div class="mt18 small muted">${due.length?`⚠ ${due.length} product(s) past or within 30 days of a recorded expiry / PAO date.`:'No recorded upcoming expiry alerts.'}</div>${due.length?btn('Review expiring products','show-expiry','','button small-btn mt12'):''}</div></div>
 ${section('Recently updated','Physical products, not just barcode entries')}${recent.length?`<div class="products">${recent.map(u=>productCard(getProduct(u.productId),[u],true)).join('')}</div>`:empty('◌','No activity yet','Your most recently added or updated products will appear here.')}`;
}
function productCard(p,units,individual=false){if(!p)return '';const active=units.filter(isActive),inUse=active.filter(u=>u.status==='in-use').length,finished=units.filter(u=>u.status==='finished').length;let sub=individual?unitLabel(units[0]):`${plural(active.length,'owned')} · ${inUse} open`;return `<button class="product-card" data-action="product-detail" data-id="${attr(p.id)}" style="text-align:left">${productImage(p)}<div class="grow" style="min-width:0"><div class="product-name">${esc(p.name)} ${p.favorite?'♡':''}</div><div class="product-meta ellipsis">${esc(p.brand||'No brand')} · ${esc(p.size||'')}${p.size?' '+esc(p.unit||'ml'):''}</div><div class="product-meta ellipsis">${esc(sub)}</div><div class="product-status row wrap">${finished&&!individual?labelPill(`${finished} finished`,'ok'):''}${labelPill(categoryName(db,p.categoryId).split(' › ').slice(-1)[0])}</div></div><span class="subtle">›</span></button>`;}
function inventory(){const s=stats(db,{categoryId:scope,period:'year'}),child=categories(db).filter(c=>c.parentId===(scope||null));let allowed=descendants(db,scope),word=search.trim().toLowerCase();let products=db.products.filter(p=>allowed.has(p.categoryId)).map(p=>({p,units:unitsFor(p.id).filter(u=>invStatus==='all'||invStatus==='active'&&isActive(u)||invStatus==='favorite'&&p.favorite&&isActive(u)||invStatus==='repurchase'&&p.repurchase&&isActive(u)||u.status===invStatus)})).filter(x=>x.units.length);
 if(word)products=products.filter(({p,units})=>[p.name,p.brand,p.barcode,categoryName(db,p.categoryId),...units.map(u=>u.location)].some(x=>String(x||'').toLowerCase().includes(word)));
 const sorters={recent:(a,b)=>Math.max(...b.units.map(x=>Date.parse(x.updatedAt||0)))-Math.max(...a.units.map(x=>Date.parse(x.updatedAt||0))),az:(a,b)=>a.p.name.localeCompare(b.p.name),oldest:(a,b)=>String(a.units[0].createdAt).localeCompare(String(b.units[0].createdAt)),price:(a,b)=>Math.max(...b.units.map(x=>money(x.price)||0))-Math.max(...a.units.map(x=>money(x.price)||0))};products.sort(sorters[invSort]||sorters.recent);
 return `${kicker('Your collection','inventory')}${crumbs(scope)}<div class="row wrap mb12">${labelPill(`${s.active} owned`,'active')}${labelPill(`${s.inUse} in use`)}${labelPill(`${s.unopened} unopened`)}${labelPill(`${efmt(s.collectionValue)} recorded value`)}</div>${child.length?`<div class="grid category-grid">${child.map(c=>{let v=stats(db,{categoryId:c.id,period:'year'});return `<button class="cat-card" data-action="category" data-id="${attr(c.id)}" style="text-align:left"><span class="cat-dot" style="background:${attr(c.color||catColor(c.id))}"></span><div class="cat-name">${esc(c.name)} ›</div><div class="row between"><div class="cat-count">${v.active}</div><div class="cat-sub">${v.finished} emptied</div></div></button>`}).join('')}</div>`:''}
 <div class="toolbar mt24"><h2 style="font-size:18px;margin:0">Products in ${esc(subtitleScope(scope))}</h2>${btn('＋ Add','add-product','','button small-btn primary')}</div><div class="filters"><input id="inv-search" placeholder="Search products, brands, locations…" value="${attr(search)}" aria-label="Search collection"><select id="inv-status" aria-label="Product status">${[['active','Owned (all)'],['in-use','In use'],['unopened','Unopened'],['favorite','Favorites'],['repurchase','Would repurchase'],['finished','Finished'],['decluttered','Decluttered'],['gifted','Given away'],['all','All records']].map(([v,k])=>`<option value="${v}" ${invStatus===v?'selected':''}>${k}</option>`).join('')}</select><select id="inv-sort" aria-label="Sort products">${[['recent','Recently updated'],['az','Name A–Z'],['oldest','Oldest added'],['price','Highest price']].map(([v,k])=>`<option value="${v}" ${invSort===v?'selected':''}>${k}</option>`).join('')}</select></div>
 ${products.length?`<div class="products">${products.map(x=>productCard(x.p,x.units)).join('')}</div>`:empty('▦','No matching products',search?'Try clearing the search or changing filters.':'Choose another status, or add a product to this category.',btn('＋ Add product','add-product','','button primary'))}`;
}
function challengeLine(ch){let p=challengeProgress(db,ch);return `<div class="mt18"><div class="row between"><span class="small strong">${esc(ch.title)}</span><span class="small ${p.exceeded?'pink':'muted'}">${esc(p.subtitle)}</span></div><div class="progress mt8"><div class="bar" style="width:${pct(p.progress)}%;background:${p.exceeded?'var(--negative)':'var(--accent)'}"></div></div></div>`}
function pan(){const active=db.challenges.filter(c=>challengeShow==='all'||(challengeShow==='active'?!c.archived:c.archived));return `${kicker('Project Pan','use what you love')}<p class="lede">Turn your collection into satisfying, measurable goals. Mark products finished or hit pan; the challenges update automatically.</p><div class="toolbar mt24">${btn('＋ New challenge','add-challenge','','button primary')}<select id="challenge-filter" style="max-width:170px"><option value="active" ${challengeShow==='active'?'selected':''}>Current projects</option><option value="archived" ${challengeShow==='archived'?'selected':''}>Archived</option><option value="all" ${challengeShow==='all'?'selected':''}>All projects</option></select></div>
 <div class="challenge-grid mt18">${active.map(c=>challengeCard(c)).join('')}</div>${!active.length?`<div class="mt18">${empty('◎','No projects yet','Try finishing 5 products, hitting pan twice, reducing your lip collection, or a no-buy challenge.',btn('Create your first challenge','add-challenge','','button primary'))}</div>`:''}
 ${section('Challenge ideas','Start with an achievable target')}<div class="grid category-grid">${[['Finish five','finish',5],['Hit pan twice','hit-pan',2],['No-buy month','no-buy',0],['Reduce stock','reduce',10]].map(([name,type,target])=>`<button class="cat-card" data-action="challenge-preset" data-type="${type}" data-goal="${target}" style="text-align:left"><div class="cat-name">${name}</div><div class="cat-sub">Create challenge →</div></button>`).join('')}</div>`;}
function challengeCard(c){const p=challengeProgress(db,c);return `<button class="challenge-card" data-action="challenge-detail" data-id="${attr(c.id)}" style="text-align:left"><div class="row between"><span class="eyebrow">${esc(c.type==='finish'?'EMPTIES':c.type==='hit-pan'?'PAN GOAL':c.type==='reduce'?'COLLECTION GOAL':c.type==='no-buy'?'NO-BUY':'SPENDING CAP')}</span>${labelPill(c.archived?'Archived':p.exceeded?'Over limit':p.met?'Completed':p.expired?'Ended':'In progress',p.exceeded?'bad':p.met?'ok':'')}</div><h3>${esc(c.title)}</h3><p>${esc(c.categoryId?getCat(c.categoryId)?.name||'Category':'All categories')} · ${shortDate(c.startDate)} – ${shortDate(c.endDate)}</p><div class="strong">${esc(p.subtitle)}</div><div class="progress"><div class="bar" style="width:${pct(p.progress)}%;background:${p.exceeded?'var(--negative)':'var(--accent)'}"></div></div><div class="small muted">${c.unitIds?.length?`${c.unitIds.length} specifically selected units`:'Any matching product'} · View details →</div></button>`;}
const periodSelect=()=>`<select id="period-filter" aria-label="Statistics period">${[['month','This month'],['year','This year'],['all','All time'],...Array.from({length:4},(_,i)=>[String(new Date().getFullYear()-i-1),String(new Date().getFullYear()-i-1)])].map(([v,t])=>`<option value="${v}" ${period===v?'selected':''}>${t}</option>`).join('')}</select>`;
function chartBars(series,key,isCurrency=false){const max=Math.max(1,...series.map(x=>x[key]));return `<div class="bar-chart" role="img" aria-label="Monthly ${key} bar chart">${series.map(x=>`<div class="bar-col" title="${esc(x.month)}: ${isCurrency?efmt(x[key]):x[key]}"><span class="bar-number">${isCurrency?efmt(x[key]):x[key]}</span><div class="bar-fill" style="height:${Math.max(2,x[key]/max*120)}px"></div><span class="x-label">${esc(x.month.slice(5))}</span></div>`).join('')}</div>`;}
function chartLine(series,key){const vals=series.map(x=>x[key]),min=Math.min(0,...vals),max=Math.max(1,...vals),points=vals.map((v,i)=>`${30+i*520/(series.length-1||1)},${160-(v-min)/(max-min)*125}`);return `<svg class="chart-area" viewBox="0 0 580 205" role="img" aria-label="Recorded collection history over ${series.length} months"><line x1="30" y1="160" x2="552" y2="160" stroke="var(--line)"/><line x1="30" y1="35" x2="552" y2="35" stroke="var(--line)" stroke-dasharray="3 4"/><polyline points="${points.join(' ')}" fill="none" stroke="var(--accent)" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="4.5" fill="var(--accent)"/><text x="${p.split(',')[0]}" y="${Math.max(18,Number(p.split(',')[1])-10)}" text-anchor="middle" font-size="12" fill="var(--fg)">${vals[i]}</text><text x="${p.split(',')[0]}" y="187" text-anchor="middle" font-size="11" fill="var(--muted)">${esc(series[i].month.slice(5))}</text>`).join('')}</svg>`;}
function insights(){const s=stats(db,{categoryId:statsScope,period}),ser=monthlySeries(db,statsScope,6),allowed=descendants(db,statsScope),cats=categories(db).filter(c=>c.parentId===(statsScope||null));const byCategory=cats.map(c=>({cat:c,s:stats(db,{categoryId:c.id,period})})).sort((a,b)=>b.s.active-a.s.active);const spmax=Math.max(1,...byCategory.map(c=>c.s.spent)),supply=supplyEstimate(db,statsScope);const budget=Number(db.settings.monthlyBudget)||0;const monthStats=stats(db,{categoryId:statsScope,period:'month'});
 return `${kicker('The numbers','your progress, quantified')}<div class="filters">${scopeSelector(statsScope,'stats-scope')}${periodSelect()}</div>${statsScope?`${crumbsForStats(statsScope)}`:''}<div class="grid kpis">${kpi('Owned now',s.active,`${s.inUse} open · ${s.unopened} sealed`)}${kpi('Finished',s.finished,`${efmt(s.emptiesValue)} used up`,'green')}${kpi('Purchased',s.purchased,`${efmt(s.spent)} spent`)}${kpi('Collection cost',efmt(s.collectionValue),`${s.collectionUnknown} products without cost`)}</div><div class="row wrap mt12">${labelPill(`${s.hitPan} pans hit`)}${labelPill(`${s.decluttered} decluttered`)}${labelPill(`${s.gifted} given away`)}${labelPill(`Net purchased − out: ${s.net>=0?'+':''}${s.net}`)}${supply?labelPill(`≈ ${supply.months} months of supply`):''}</div>
 <div class="two-col mt24"><div class="card"><div class="strong">Last six months · spending</div>${chartBars(ser,'spending',true)}<div class="chart-caption">Paid purchases with a recorded purchase date; existing items are excluded.</div></div><div class="card"><div class="strong">Last six months · empties</div>${chartBars(ser,'finished')}<div class="chart-caption">Products marked finished in each month.</div></div></div><div class="card mt18"><div class="strong">Recorded collection trend</div>${chartLine(ser,'collection')}<div class="chart-caption">Collection entries made in this app, not a reconstruction of inventory before tracking began. A product remains counted until its recorded finish / exit month.</div></div>
 ${section('Year in review',`Your ${new Date().getFullYear()} snapshot`)}${(()=>{const annual=stats(db,{categoryId:statsScope,period:'year'});const yearlyCats=categories(db).filter(c=>c.parentId===(statsScope||null)).map(c=>({name:c.name,info:stats(db,{categoryId:c.id,period:'year'})}));const emptied=yearlyCats.slice().sort((a,b)=>b.info.finished-a.info.finished)[0];const spentMost=yearlyCats.slice().sort((a,b)=>b.info.spent-a.info.spent)[0];return `<div class="card"><div class="stat-split"><div class="micro"><strong>${annual.finished}</strong><span>Empties this year</span></div><div class="micro"><strong>${efmt(annual.emptiesValue)}</strong><span>Empties cost</span></div><div class="micro"><strong>${efmt(annual.spent)}</strong><span>Purchases paid</span></div></div><div class="data-row mt18"><span class="muted small">Most products finished in</span><b>${esc(emptied?.info.finished?emptied.name:'—')}</b></div><div class="data-row"><span class="muted small">Highest spending category</span><b>${esc(spentMost?.info.spent?spentMost.name:'—')}</b></div></div>`})()}
 ${section('Drill into categories','Tap any row to go deeper')}${byCategory.length?`<div class="grid category-grid">${byCategory.map(({cat,s})=>`<button class="cat-card" data-action="stats-category" data-id="${attr(cat.id)}" style="text-align:left"><span class="cat-dot" style="background:${attr(cat.color||catColor(cat.id))}"></span><div class="cat-name">${esc(cat.name)} →</div><div class="cat-count">${s.active}</div><div class="cat-sub">${s.finished} empties · ${efmt(s.spent)} spent</div></button>`).join('')}</div>`:`<div class="soft-card small muted">Selected category is the most detailed level. Use the scope selector to compare it with other categories.</div>`}
 <div class="two-col mt18"><div class="card"><div class="strong">Spending by subcategory</div><div class="spend-list mt18">${byCategory.map(({cat,s})=>`<div class="spend-item"><div class="top"><span>${esc(cat.name)}</span><strong>${efmt(s.spent)}</strong></div><div class="progress"><div class="bar" style="width:${pct(s.spent/spmax*100)}%"></div></div></div>`).join('')||'<div class="muted small">Choose a broader category for a breakdown.</div>'}</div></div><div class="card"><div class="strong">Useful comparisons</div><div class="data-row mt18"><span class="muted small">Recorded purchase cost of empties</span><b>${efmt(s.emptiesValue)}</b></div><div class="data-row"><span class="muted small">Products finished</span><b>${s.finished}</b></div><div class="data-row"><span class="muted small">This month’s spending</span><b>${efmt(monthStats.spent)}</b></div>${budget?`<div class="data-row"><span class="muted small">Monthly budget</span><b>${efmt(budget)}</b></div><div class="progress mt12"><div class="bar" style="width:${pct(monthStats.spent/budget*100)}%;background:${monthStats.spent>budget?'var(--negative)':'var(--accent)'}"></div></div>`:''}${supply?`<p class="small muted">Estimated ${supply.months} months of supply from ${supply.finished} empties recorded over ${supply.observedMonths} months. Estimates are indicative.</p>`:'<p class="small muted">Months-of-supply estimates appear after at least two months of tracked history with an empty.</p>'}${s.collectionUnknown||s.spentUnknown||s.undatedPurchases||s.emptiesUnknown?`<p class="small muted">Missing data: ${s.collectionUnknown} active products without prices; ${s.spentUnknown} dated purchases without prices; ${s.emptiesUnknown} empties without prices; ${s.undatedPurchases} purchases without dates. Money totals include known prices only, and spending by period requires purchase dates.</p>`:''}</div></div>`;}
function crumbsForStats(id){return `<div class="breadcrumb"><button class="crumb" data-action="stats-category" data-id="">All categories</button>${catPath(db,id).map(c=>`<span class="subtle">›</span><button class="crumb" data-action="stats-category" data-id="${attr(c.id)}">${esc(c.name)}</button>`).join('')}</div>`;}
function wishlist(){const items=db.wishlist.filter(w=>wishlistShow==='all'||(wishlistShow==='open'?!w.purchasedAt:!!w.purchasedAt)).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));return `${kicker('Wishlist & replacements','shop thoughtfully')}<p class="lede">Keep replacements you actually need separate from things you'd simply like to try.</p><div class="toolbar mt24">${btn('＋ Add wish','add-wish','','button primary')}<select id="wish-filter" style="max-width:170px"><option value="open" ${wishlistShow==='open'?'selected':''}>Still wanted</option><option value="purchased" ${wishlistShow==='purchased'?'selected':''}>Purchased</option><option value="all" ${wishlistShow==='all'?'selected':''}>All wishes</option></select></div><div class="grid mt18" style="gap:9px">${items.map(w=>`<button class="card wish-card" data-action="wish-detail" data-id="${attr(w.id)}" style="text-align:left"><div><div class="row wrap"><b>${esc(w.name)}</b>${labelPill(w.type==='replacement'?'Replacement':'Wishlist',w.type==='replacement'?'active':'')}${w.purchasedAt?labelPill('Purchased','ok'):''}</div><div class="small muted mt8">${esc(w.brand||'Unbranded')} · ${esc(categoryName(db,w.categoryId))}</div>${w.notes?`<div class="small muted mt8">${esc(w.notes)}</div>`:''}</div><div class="right"><b>${w.estimatedPrice!=null?efmt(w.estimatedPrice):'—'}</b><div class="small subtle mt8">›</div></div></button>`).join('')}</div>${!items.length?`<div class="mt18">${empty('♡','A thoughtful wishlist','Add a replacement or something you want to try. Wishes do not count as purchases.',btn('Add wish','add-wish','','button primary'))}</div>`:''}`;}
function settings(){const custom=db.categories.slice().sort((a,b)=>categoryName(db,a.id).localeCompare(categoryName(db,b.id)));return `${kicker('Settings','make it yours')}<div class="settings-section"><h2>Appearance & money</h2><div class="setting-row"><span>Theme</span><select id="theme-select"><option value="dark" ${db.settings.theme==='dark'?'selected':''}>True black</option><option value="light" ${db.settings.theme==='light'?'selected':''}>Light</option></select></div><div class="setting-row"><span>Currency</span><select id="currency-select">${['EUR','USD','GBP','SEK','NOK','DKK','CHF'].map(c=>`<option value="${c}" ${db.settings.currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="setting-row"><span>Monthly spending budget <span class="tiny muted">(optional)</span></span><input type="number" id="budget-input" min="0" step="0.01" value="${db.settings.monthlyBudget??''}" placeholder="No budget" style="max-width:205px"></div>${btn('Save settings','save-settings','','button primary small-btn')}</div>
 <div class="settings-section"><h2>Detailed categories</h2><p>Over ${BUILTIN_CATEGORIES.length} built-in category levels, including dozens of specific product types. Add as many custom sections and leaves as you need. Every level can be analysed separately.</p>${btn('＋ Add custom category','add-category','','button small-btn primary')}<div class="mt18">${custom.map(c=>`<div class="data-row"><div class="small"><strong>${esc(c.name)}</strong><div class="muted tiny">${esc(categoryName(db,c.id))}</div></div><div class="row">${btn('Rename','rename-category',`data-id="${attr(c.id)}"`,'button small-btn')}${btn('Delete','delete-category',`data-id="${attr(c.id)}"`,'button small-btn danger')}</div></div>`).join('')||'<div class="small muted">No custom categories yet.</div>'}</div></div>
 <div class="settings-section"><h2>Backup & restore</h2><p>Everything stays in this browser’s local storage, including product photos. Export a JSON backup regularly, especially before clearing browser data or changing phones. Backups may contain sensitive purchase details and photos.</p><div class="row wrap">${btn('↓ Export complete JSON','export','','button primary')}${btn('↑ Import / merge JSON','import','','button')}</div></div>
 <div class="settings-section"><h2>App & privacy</h2><p>No account, no sync, no analytics. The app works offline after the first load. Barcode lookup uses Open Beauty Facts when online; your barcode is sent only to that service for lookup. If camera scanning is unsupported natively, a scanner library may be loaded from a CDN when you first use it online.</p><div class="row wrap">${btn('Install app','install','','button')}${btn('Check for updates','check-update','','button')}${btn('Load example collection','demo','','button')}</div><div id="update-alert" class="mt12">${workerWaiting?`<div class="notice info">A new app version is ready. ${btn('Apply update','apply-update','','button small-btn primary')} (does not automatically interrupt editing)</div>`:''}</div></div>
 <div class="settings-section"><h2>Danger zone</h2><p>Deleting everything cannot be undone without a backup.</p>${btn('Erase all local app data','erase','','button danger')}</div><div class="small subtle mt24">Project Pan · v1.0 · Works best installed over HTTPS on your phone.</div>`;}
function render(){document.body.className='theme-'+(db.settings.theme==='light'?'light':'dark');$('#page').innerHTML=({home,inventory,pan,insights,wishlist,settings}[page]||home)();document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#add-fab').style.display=page==='settings'?'none':'';document.querySelector('meta[name="theme-color"]').content=db.settings.theme==='dark'?'#000000':'#f7f6f9';}
function renderPreserve(){const a=document.activeElement,key=a?.id,pos=a?.selectionStart;render();if(key){let next=document.getElementById(key);if(next){next.focus();if(typeof pos==='number'&&next.setSelectionRange)next.setSelectionRange(pos,pos)}}}
// Modal forms. Every physical unit has its own dates, status and cost.
const field=(title,name,value='',type='text',extra='',hint='')=>`<div class="field"><label for="f-${attr(name)}">${title}</label><input id="f-${attr(name)}" name="${attr(name)}" type="${type}" value="${attr(value??'')}" ${extra}>${hint?`<div class="help">${hint}</div>`:''}</div>`;
const selectField=(title,name,choices,value='',wide=false)=>`<div class="field ${wide?'wide':''}"><label for="f-${attr(name)}">${title}</label><select id="f-${attr(name)}" name="${attr(name)}">${choices.map(([id,label])=>`<option value="${attr(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('')}</select></div>`;
function openDialog(title,body,footer=''){closeModal();openModal=title;$('#modal-root').innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${attr(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</div></div>`;const focus=$('#modal-root input:not([type="hidden"]),#modal-root select');focus?.focus({preventScroll:true});}
function closeModal(){lookupToken++;stopScanner();$('#modal-root').innerHTML='';openModal='';modalPayload=null;}
function formFooter(formId,text='Save product'){return `<button type="button" data-action="close-modal" class="button">Cancel</button><button type="submit" form="${formId}" class="button primary">${text}</button>`;}
const extraDates=u=>`<div class="form-grid mt12">${field('Date opened','openedAt',u?.openedAt||'','date', '', 'Optional; used to calculate period-after-opening dates.')}${field('Date finished / exited','closedDate',u?.finishedAt||u?.closedAt||'','date')}${field('Expiry / best-before','expiryDate',u?.expiryDate||'','date')}${field('PAO months','paoMonths',u?.paoMonths||'','number','min="0" step="1" placeholder="e.g. 12"','Period after opening, if the packaging specifies it.')}${field('Location','location',u?.location||'','text','list="location-list" placeholder="Bathroom, storage, handbag…"')}<datalist id="location-list">${[...new Set(db.units.map(x=>x.location).filter(Boolean))].map(x=>`<option value="${attr(x)}"></option>`).join('')}</datalist>${field('Remaining (%)','remaining',u?.remaining??100,'number','min="0" max="100" step="5"')}${field('Date hit pan (optional)','hitPanAt',u?.hitPanAt||'','date')}</div>`;
function categorySelect(id=''){const all=categories(db),leaves=all.filter(c=>!all.some(other=>other.parentId===c.id)||c.id===id);return `<div class="field wide"><label for="f-categoryId">Specific category *</label><input id="category-search" type="search" placeholder="Search categories: lip gloss, cleanser, shampoo…" aria-label="Find a category"><select name="categoryId" id="f-categoryId" required><option value="">Choose a product type…</option>${leaves.map(c=>`<option value="${attr(c.id)}" ${id===c.id?'selected':''}>${esc(categoryName(db,c.id))}</option>`).join('')}</select><div class="help">Search or browse to the narrowest product type. Add custom categories in Settings.</div></div>`;}
function filterCategories(query){const select=$('#f-categoryId');if(!select)return;const keep=select.value,q=query.toLowerCase().trim(),all=categories(db),leaves=all.filter(c=>!all.some(other=>other.parentId===c.id)||c.id===keep),hits=leaves.filter(c=>categoryName(db,c.id).toLowerCase().includes(q));select.innerHTML='<option value="">Choose a product type…</option>'+hits.map(c=>`<option value="${attr(c.id)}">${esc(categoryName(db,c.id))}</option>`).join('');if(hits.some(c=>c.id===keep))select.value=keep;else if(hits.length===1)select.value=hits[0].id;}

function productForm(p=null,opts={}){const edit=!!p,existing=opts.wishId?db.wishlist.find(w=>w.id===opts.wishId):null;const source=opts.scanData||{};let init={name:p?.name||existing?.name||source.name||'',brand:p?.brand||existing?.brand||source.brand||'',barcode:p?.barcode||source.barcode||'',size:p?.size||source.size||'',unit:p?.unit||source.unit||'ml',categoryId:p?.categoryId||existing?.categoryId||source.categoryId||scope||'',notes:p?.notes||'',image:p?.image||source.image||'',favorite:p?.favorite||false,repurchase:p?.repurchase||false};
 const body=`<form id="product-form"><input type="hidden" name="productId" value="${attr(p?.id||'')}"><input type="hidden" name="wishId" value="${attr(opts.wishId||'')}"><div class="form-grid">${field('Product name *','name',init.name,'text','required maxlength="130"')}${field('Brand','brand',init.brand,'text','maxlength="100"')}${field('Barcode','barcode',init.barcode,'text','inputmode="numeric" maxlength="30" placeholder="EAN / UPC"')}${field('Size / amount','size',init.size,'number','min="0" step="any"')}${selectField('Unit','unit',[['ml','ml'],['g','g'],['pcs','pieces'],['oz','oz'],['other','other']],init.unit)}${categorySelect(init.categoryId)}<div class="field wide"><label for="f-photo">Product photo (optional)</label><input id="f-photo" name="photo" type="file" accept="image/*"><div class="help">Photos are resized and stored privately in this app. ${init.image?'The existing image remains unless you add another.':''}</div>${init.image?`<div class="mt8"><img class="image-preview" src="${attr(init.image)}" alt="Current product image"></div>`:''}</div><div class="field wide"><div class="row wrap"><label class="checkline"><input type="checkbox" name="favorite" ${init.favorite?'checked':''}> Favorite</label><label class="checkline"><input type="checkbox" name="repurchase" ${init.repurchase?'checked':''}> Would repurchase</label></div></div><div class="field wide"><label for="f-notes">Product notes</label><textarea id="f-notes" name="notes" placeholder="Shade, scent, thoughts, ingredients…">${esc(init.notes)}</textarea></div></div>
 ${edit?'':`<div class="section-heading"><h2>Physical product(s)</h2><span class="hint">One shared product definition</span></div><div class="form-grid">${unitBaseFields(null,true)}</div>`}</form>`;
 openDialog(edit?'Edit product':'Add a product',body,formFooter('product-form',edit?'Save changes':'Add to collection'));modalPayload=opts.scanData||null;
}
function unitBaseFields(u=null,quantity=false){const acquisition=u?.acquisition||'existing',status=u?.status||'unopened';return `<div class="field wide"><div class="notice info">${u?'Edit this physical item only.':'Already owned items can have a known cost without counting toward newly recorded spending.'}</div></div>${quantity?field('Number of identical units','quantity',1,'number','min="1" max="99" step="1"'):''}
 ${selectField('How acquired','acquisition',[['existing','Already owned (not new spending)'],['purchase','Purchased'],['gift','Received as gift']],acquisition)}
 ${selectField('Status','status',Object.entries(statusName),status)}
 ${field('Price you paid per unit','price',u?.price??'','number','min="0" step="0.01" placeholder="Unknown"')}
 ${field('Purchase date','purchaseDate',u?.purchaseDate||'','date','', 'Only purchased items with a date count toward monthly / yearly spending.')}
 <div class="field wide"><label class="small muted">Usage and dates</label></div>${extraDates(u)}`;}
function newUnitForm(productId){let p=getProduct(productId);if(!p)return;openDialog('Add another unit',`<form id="unit-form"><input name="unitId" type="hidden" value=""><input name="productId" type="hidden" value="${attr(productId)}"><div class="small muted mb12">${esc(p.brand||'')} ${esc(p.name)} — one new physical product, with its own cost and dates.</div><div class="form-grid">${unitBaseFields(null,true)}</div></form>`,formFooter('unit-form','Add units'));}
function editUnitForm(unitId){let u=getUnit(unitId),p=u&&getProduct(u.productId);if(!u||!p)return;openDialog('Edit physical product',`<form id="unit-form"><input name="unitId" type="hidden" value="${attr(unitId)}"><input name="productId" type="hidden" value="${attr(p.id)}"><div class="small muted mb12">${esc(p.brand||'')} ${esc(p.name)} · Each unit is recorded separately.</div><div class="form-grid">${unitBaseFields(u)}</div></form>`,formFooter('unit-form','Save unit'));}
function productDetail(id){const p=getProduct(id);if(!p)return;const units=unitsFor(id).slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));openDialog(p.name,`<div class="detail-head">${productImage(p)}<div class="grow"><div class="small muted">${esc(p.brand||'Unbranded')}</div><h3>${esc(p.name)} ${p.favorite?'♡':''}</h3><div class="small muted">${esc(categoryName(db,p.categoryId))}</div><div class="small muted mt8">${esc(p.size||'')}${p.size?' '+esc(p.unit):''} ${p.barcode?'· '+esc(p.barcode):''}</div></div></div><div class="row wrap mt18">${btn('＋ Add another','add-unit',`data-id="${attr(p.id)}"`,'button primary small-btn')}${btn('Edit product','edit-product',`data-id="${attr(p.id)}"`,'button small-btn')}${btn('Add to wishlist','product-to-wish',`data-id="${attr(p.id)}"`,'button small-btn')}</div>${p.notes?`<div class="small muted mt12">${esc(p.notes)}</div>`:''}<div class="section-heading"><h2>Physical units (${units.length})</h2><span class="hint">Independent histories</span></div>${units.length?units.map((u,i)=>{let ex=expiryInfo(u);return `<div class="unit-card"><div class="row between"><b class="small">Unit ${units.length-i} · ${esc(statusName[u.status])}</b>${labelPill(u.price!==null&&u.price!==''?efmt(u.price):'No price',isActive(u)?'active':'')}</div><div class="small muted mt8">${esc(acqName[u.acquisition]||'Already owned')} ${u.purchaseDate?' · '+shortDate(u.purchaseDate):''} · ${esc(u.location||'No location')}</div>${isActive(u)?`<div class="mini-track"><div class="progress"><div class="bar" style="width:${pct(u.remaining??100)}%"></div></div><span class="tiny muted">${pct(u.remaining??100)}% left</span></div>`:''}${ex?`<div class="small mt8 ${ex.level==='overdue'?'pink':ex.level==='soon'?'accent':'muted'}">${esc(ex.why)}: ${shortDate(ex.date)} ${ex.level==='overdue'?'· past date':ex.level==='soon'?'· due soon':''}</div>`:''}${u.openedAt?`<div class="tiny muted mt8">Opened ${shortDate(u.openedAt)}</div>`:''}${u.finishedAt?`<div class="tiny green mt8">Finished ${shortDate(u.finishedAt)}</div>`:''}${u.hitPanAt?`<div class="tiny green mt8">Hit pan ${shortDate(u.hitPanAt)}</div>`:''}<div class="row wrap mt12">${isActive(u)?btn('✓ Finish','finish-unit',`data-id="${attr(u.id)}"`,'button primary small-btn'):''}${isActive(u)&&!u.hitPanAt?btn('◎ Hit pan','hit-pan',`data-id="${attr(u.id)}"`,'button small-btn'):''}${btn('Edit','edit-unit',`data-id="${attr(u.id)}"`,'button small-btn')}${btn('Delete unit','delete-unit',`data-id="${attr(u.id)}"`,'button danger small-btn')}</div></div>`}).join(''):empty('◌','No units','Add the first physical unit for this product.')}
 <div class="mt24">${btn('Delete product definition','delete-product',`data-id="${attr(p.id)}"`,'button danger small-btn')}</div>`);}
const toUnit=(fd,prior=null)=>{
 const now=today(),status=String(fd.get('status')||'unopened'),closed=fd.get('closedDate')||'',result={...(prior||{}),
 acquisition:String(fd.get('acquisition')||'existing'),status,price:money(fd.get('price')),purchaseDate:String(fd.get('purchaseDate')||''),openedAt:String(fd.get('openedAt')||''),finishedAt:status==='finished'?(closed||prior?.finishedAt||now):'',closedAt:['decluttered','gifted'].includes(status)?(closed||prior?.closedAt||now):'',expiryDate:String(fd.get('expiryDate')||''),paoMonths:Number(fd.get('paoMonths'))||0,location:String(fd.get('location')||'').trim().slice(0,90),remaining:status==='finished'?0:pct(fd.get('remaining')),hitPanAt:String(fd.get('hitPanAt')||'')};
 if(status==='in-use'&&!result.openedAt)result.openedAt=now;
 if(result.acquisition==='purchase'&&!result.purchaseDate&&!prior)result.purchaseDate=now;
 if(!prior){result.id=uid('u');result.createdAt=stamp()};return touch(result);
};
async function readPhoto(file){if(!file||!file.size)return null;if(file.size>15e6)throw Error('Photo is too large (15 MB max).');let objectUrl=URL.createObjectURL(file);try{let img=new Image;await new Promise((ok,no)=>{img.onload=ok;img.onerror=()=>no(Error('Could not read photo'));img.src=objectUrl});const max=560,ratio=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.77)}finally{URL.revokeObjectURL(objectUrl)}}
async function submitProduct(form){const fd=new FormData(form);const id=fd.get('productId'),editingProduct=!!id,old=id?getProduct(id):null,photo=fd.get('photo');let picture;
 try{picture=photo?.size?await readPhoto(photo):null}catch(e){showToast(e.message);return}
 const name=String(fd.get('name')||'').trim(),categoryId=String(fd.get('categoryId')||'');if(!name||!getCat(categoryId)){showToast('Choose a product name and category');return}
 const code=String(fd.get('barcode')||'').trim();let collision=code&&db.products.find(p=>p.barcode===code&&p.id!==id);
 if(collision&&!confirm(`That barcode already belongs to “${collision.name}”. Save this as a separate product definition anyway? For a duplicate item, use Add another unit instead.`))return;
 const p=touch({...(old||{}),id:old?.id||uid('p'),createdAt:old?.createdAt||stamp(),name:name.slice(0,130),brand:String(fd.get('brand')||'').trim().slice(0,100),barcode:code,size:money(fd.get('size')),unit:String(fd.get('unit')||'ml'),categoryId,image:picture||old?.image||modalPayload?.image||'',favorite:fd.has('favorite'),repurchase:fd.has('repurchase'),notes:String(fd.get('notes')||'').trim().slice(0,4000)});
 const qty=editingProduct?0:Math.min(99,Math.max(1,Number(fd.get('quantity'))||1));const units=Array.from({length:qty},()=>({...toUnit(fd),productId:p.id}));
 const wishId=fd.get('wishId');change(d=>{if(editingProduct)d.products=d.products.map(x=>x.id===p.id?p:x);else d.products.push(p);d.units.push(...units);if(wishId&&qty){const w=d.wishlist.find(x=>x.id===wishId);if(w){w.purchasedAt=today();w.linkedProductId=p.id;touch(w)}}});closeModal();showToast(editingProduct?'Product saved':`${qty} product${qty===1?'':'s'} added`);if(/^https:\/\//.test(p.image))cacheProductImage(p.id,p.image);
}
async function cacheProductImage(id,url){ // Optional, asynchronous; never blocks the Save action.
 try{if(!navigator.onLine)return;const c=new AbortController(),timer=setTimeout(()=>c.abort(),8000);let res;try{res=await fetch(url,{signal:c.signal})}finally{clearTimeout(timer)}if(!res?.ok)return;const blob=await res.blob();if(blob.size>5e6)return;const data=await readPhoto(new File([blob],'image.jpg',{type:blob.type||'image/jpeg'}));const p=getProduct(id);if(p?.image===url){change(d=>{touch(d.products.find(x=>x.id===id)).image=data},{silent:true})}}catch(e){console.info('Remote product photo was not cached locally',e.message)}
}
