function exportBackup(){const payload={...db,exportedAt:stamp(),app:'Project Pan'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`project-pan-backup-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);showToast('Backup exported');}
function importDialog(){openDialog('Import your backup',`<div class="notice info">Replace swaps in the imported collection. Merge compares individual records by last edit time; newer edits and deletions win. Current settings remain unchanged when merging. Export your current data first if you want a rollback.</div><div class="field mt18"><label for="backup-file">Choose a Project Pan JSON backup</label><input id="backup-file" type="file" accept="application/json,.json"></div><div id="backup-preview" class="small muted mt12">No file selected.</div><div class="row wrap mt18">${btn('Merge backup','merge-backup','','button primary hidden')}${btn('Replace everything','replace-backup','','button danger hidden')}</div>`);}
let importCandidate=null;
async function backupChosen(file){if(!file)return;try{if(file.size>60*1024*1024)throw Error('Backup exceeds 60 MB');const imported=JSON.parse(await file.text());if(!validBackup(imported))throw Error('This is not a compatible Project Pan v1 backup');importCandidate=imported;$('#backup-preview').innerHTML=`<b>Compatible backup</b><div>${imported.products.length} product definitions · ${imported.units.length} physical units · ${imported.challenges.length} challenges · ${imported.wishlist.length} wishes</div><div>Exported: ${esc(imported.exportedAt||'Unknown date')}</div>`;document.querySelectorAll('[data-action="merge-backup"],[data-action="replace-backup"]').forEach(b=>b.classList.remove('hidden'));}catch(e){importCandidate=null;$('#backup-preview').textContent='Import failed: '+e.message;}}
function importApply(kind){if(!importCandidate)return;if(!confirm(kind==='replace'?'Replace all current local data with this backup?':'Merge this backup into your current data, preserving newer edits?'))return;db=kind==='merge'?mergeData(db,importCandidate):structuredClone(importCandidate);if(!db.barcodeCache)db.barcodeCache={};if(!db.tombstones)db.tombstones=blank().tombstones;db.settings={...blank().settings,...db.settings};scope=null;statsScope=null;page='home';save();closeModal();importCandidate=null;render();showToast('Backup '+(kind==='merge'?'merged':'restored'));}
function updateBanner(){workerWaiting=!!navigator.serviceWorker&&!!navigator.serviceWorker.controller&&!!window.__swRegistration?.waiting;if(page==='settings')render();}
let updateRequested=false;
async function initSW(){if(!('serviceWorker' in navigator)||!location.protocol.startsWith('http'))return;try{const reg=await navigator.serviceWorker.register('./service-worker.js');window.__swRegistration=reg;if(reg.waiting)updateBanner();reg.addEventListener('updatefound',()=>{const w=reg.installing;if(w)w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller){workerWaiting=true;showToast('App update ready in Settings');if(page==='settings')render()}})});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updateRequested)location.reload()})}catch(e){console.warn('Offline install unavailable:',e)}}
const installApp=async()=>{if(pendingInstall){pendingInstall.prompt();const result=await pendingInstall.userChoice;if(result?.outcome==='accepted')pendingInstall=null}else showToast('Use your browser menu → Add to Home screen / Install app.');};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();pendingInstall=e});
// Every mutation flows through the same persistence layer and re-renders the current view.
async function handleAction(action,el){const id=el.dataset.id;
 switch(action){
 case 'close-modal':closeModal();break;
 case 'add-product':productForm();break;
 case 'scan':scanDialog();break;
 case 'category':scope=id||null;invStatus='active';search='';navigate('inventory');break;
 case 'stats-category':statsScope=id||null;render();break;
 case 'product-detail':productDetail(id);break;
 case 'edit-product':productForm(getProduct(id));break;
 case 'add-unit':newUnitForm(id);break;
 case 'edit-unit':editUnitForm(id);break;
 case 'finish-unit':{const u=getUnit(id);if(!u||!isActive(u))return;change(d=>{const x=d.units.find(u=>u.id===id);x.status='finished';x.finishedAt=today();x.closedAt='';x.remaining=0;touch(x)});productDetail(u.productId);showToast('One more empty!');break;}
 case 'hit-pan':{const u=getUnit(id);if(!u||u.hitPanAt)return;change(d=>{let x=d.units.find(u=>u.id===id);x.hitPanAt=today();touch(x)});productDetail(u.productId);showToast('You hit pan!');break;}
 case 'delete-unit':{const u=getUnit(id);if(u&&confirm('Delete this specific physical unit? This also changes past statistics.')){change(d=>deleteRecord(d,'units',id));productDetail(u.productId)}break;}
 case 'delete-product':{if(db.units.some(u=>u.productId===id)){showToast('Delete the physical units first to keep history consistent.');return}if(confirm('Delete this product definition?')){change(d=>deleteRecord(d,'products',id));closeModal()}break;}
 case 'product-to-wish':{const p=getProduct(id);if(p){wishForm(null,p)}break;}
 case 'add-challenge':challengeForm();break;
 case 'challenge-preset':challengeForm(null,{type:el.dataset.type,goal:Number(el.dataset.goal)});break;
 case 'challenge-detail':challengeDetail(id);break;
 case 'edit-challenge':challengeForm(db.challenges.find(x=>x.id===id));break;
 case 'archive-challenge':{const c=db.challenges.find(x=>x.id===id);if(c)change(d=>{touch(d.challenges.find(x=>x.id===id)).archived=!c.archived});closeModal();break;}
 case 'delete-challenge':if(confirm('Permanently delete this challenge?')){change(d=>deleteRecord(d,'challenges',id));closeModal()}break;
 case 'add-wish':wishForm();break;
 case 'wish-detail':wishDetail(id);break;
 case 'edit-wish':wishForm(db.wishlist.find(x=>x.id===id));break;
 case 'wish-to-product':productForm(null,{wishId:id});break;
 case 'wish-acquired':change(d=>{let w=d.wishlist.find(x=>x.id===id);w.purchasedAt=today();touch(w)});closeModal();break;
 case 'delete-wish':if(confirm('Delete this wishlist item?')){change(d=>deleteRecord(d,'wishlist',id));closeModal()}break;
 case 'add-category':categoryForm();break;
 case 'rename-category':categoryForm(db.categories.find(x=>x.id===id));break;
 case 'delete-category':{let c=db.categories.find(x=>x.id===id);if(!c)return;if(categories(db).some(x=>x.parentId===id)||db.products.some(p=>p.categoryId===id)||db.wishlist.some(w=>w.categoryId===id)||db.challenges.some(ch=>ch.categoryId===id)){showToast('This category has products, wishes, goals, or subcategories. Reassign them first.');return}if(confirm(`Delete custom category “${c.name}”?`))change(d=>deleteRecord(d,'categories',id));break;}
 case 'save-settings':{const currency=$('#currency-select').value,theme=$('#theme-select').value,v=$('#budget-input').value;change(d=>{d.settings={...d.settings,currency,theme,monthlyBudget:v===''?null:Math.max(0,Number(v))}});showToast('Settings updated');break;}
 case 'export':exportBackup();break;
 case 'import':importCandidate=null;importDialog();break;
 case 'merge-backup':importApply('merge');break;
 case 'replace-backup':importApply('replace');break;
 case 'demo':if(confirm('Load six explicitly fictional example products into your existing collection? (They will be marked as demo examples.)')){const example=demo();change(d=>{const incoming=mergeData(d,example);Object.assign(d,incoming)});showToast('Example items added')}break;
 case 'erase':if(confirm('Erase ALL Project Pan inventory, photos, history, goals and settings on this device?')&&confirm('Final confirmation: this cannot be undone without a JSON backup.')){db=blank();save();scope=null;statsScope=null;navigate('home');showToast('Local data erased')}break;
 case 'install':await installApp();break;
 case 'check-update':{const reg=window.__swRegistration;if(reg){await reg.update();workerWaiting=!!reg.waiting;render();showToast(workerWaiting?'Update ready to apply':'No update waiting')}else showToast('App not installed / service worker unavailable');break;}
 case 'apply-update':{const reg=window.__swRegistration;if(reg?.waiting){updateRequested=true;reg.waiting.postMessage({type:'SKIP_WAITING'});}break;}
 case 'start-camera':startCamera();break;
 case 'stop-camera':stopScanner();scanStatus('Camera stopped');break;
 case 'show-expiry':showExpiry();break;
 default:break;
 }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-page]');if(!b)return;const modalOpen=!!$('#modal-root .modal');if(b.dataset.page){if(modalOpen)return;navigate(b.dataset.page);return}handleAction(b.dataset.action,b).catch?.(err=>{console.error(err);showToast('Something went wrong: '+err.message)})});
document.addEventListener('submit',e=>{const f=e.target,formId=f?.getAttribute?.('id');if(!formId)return;e.preventDefault();let task;
 if(formId==='product-form')task=submitProduct(f);else if(formId==='unit-form')task=submitUnit(f);else if(formId==='challenge-form')task=submitChallenge(f);else if(formId==='wish-form')task=submitWish(f);else if(formId==='category-form')task=submitCategory(f);else if(formId==='barcode-form')task=foundBarcode(new FormData(f).get('barcode'));
 Promise.resolve(task).catch(err=>{console.error(err);showToast('Could not save: '+err.message)});
});
document.addEventListener('change',e=>{const t=e.target;
 if(t.id==='inv-status'){invStatus=t.value;render()}else if(t.id==='inv-sort'){invSort=t.value;render()}else if(t.id==='category-filter'){statsScope=t.value||null;render()}else if(t.id==='period-filter'){period=t.value;render()}else if(t.id==='wish-filter'){wishlistShow=t.value;render()}else if(t.id==='challenge-filter'){challengeShow=t.value;render()}else if(t.id==='backup-file')backupChosen(t.files?.[0]);else if(t.id==='scan-image')scanImage(t.files?.[0]);else if(t.name==='acquisition'&&t.value==='purchase'){const date=$('#f-purchaseDate');if(date&&!date.value)date.value=today();}
});
document.addEventListener('input',e=>{if(e.target.id==='inv-search'){search=e.target.value;renderPreserve()}else if(e.target.id==='category-search')filterCategories(e.target.value)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&openModal)closeModal()});
document.addEventListener('click',e=>{if(e.target.id==='backdrop')closeModal()});
(async()=>{try{const stored=await load();if(validBackup(stored))db={...blank(),...stored,settings:{...blank().settings,...stored.settings}};else if(stored?.units?.length)showToast('Storage format not recognised; new empty collection shown');}catch(e){storageError=true;console.error(e);showToast('Local storage unavailable; changes may not persist.')}render();initSW();})();
